package com.onlinehomework.grading.application;
import com.onlinehomework.grading.domain.GradeStatus; import com.onlinehomework.grading.persistence.GradeRevisionRepository; import com.onlinehomework.submission.application.CurrentPublishedGradeQuery; import org.springframework.stereotype.Component; import java.util.*;
@Component public class PublishedGradeQueryAdapter implements CurrentPublishedGradeQuery { private final GradeRevisionRepository r; public PublishedGradeQueryAdapter(GradeRevisionRepository r){this.r=r;} public Optional<PublishedGradeView> findCurrentPublishedGrade(UUID id){return r.findAllBySubmissionIdOrderByRevisionDesc(id).stream().filter(g->g.getStatus()==GradeStatus.PUBLISHED).findFirst().map(g->new PublishedGradeView(g.getId(),g.getSubmissionId(),g.getRevision(),g.getScore(),g.getFeedback(),g.getCreatedAt(),g.getPublishedAt()));} }
